function handleInquiry(event) {
  event.preventDefault();
  const form = event.currentTarget;
  if (!form.reportValidity()) return;
  if (![form.elements.name,form.elements.message].every(el => el.value.trim().length)) {
    document.getElementById('form-status').textContent = t('Preencha nome e mensagem com conteúdo válido.','Enter a valid name and message.'); return;
  }
  const text = `KAV CLASS — ${t('Solicitação de contato','Contact request')}\n\n${t('Nome','Name')}: ${form.elements.name.value.trim()}\nEmail: ${form.elements.email.value.trim()}\n${t('Empresa','Company')}: ${form.elements.company.value.trim()}\n${t('Interesse','Interest')}: ${form.elements.interest.selectedOptions[0].text}\n\n${form.elements.message.value.trim()}`;
  if (hasContact) {
    window.location.href = `mailto:${config.contactEmail}?subject=${encodeURIComponent('KAV CLASS — '+form.elements.interest.selectedOptions[0].text)}&body=${encodeURIComponent(text)}`;
    document.getElementById('form-status').textContent = t('Revise e envie no seu aplicativo de e-mail. O site não confirma o envio.','Review and send in your email app. This site does not confirm delivery.');
  } else {
    const url = URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));
    const link = document.createElement('a'); link.href = url; link.download = 'kav-class-contact-request.txt'; document.body.append(link); link.click(); link.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000);
    document.getElementById('form-status').textContent = t('Solicitação preparada para download. Nenhuma mensagem foi enviada.','Request prepared for download. No message has been sent.');
  }
}
render();
